using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check project dependencies
Console.WriteLine("=== PROJECT STRUCTURE ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"Project: {p.Name} -> Succeeded={p.Succeeded}");
}

// Check if Api references Services
Console.WriteLine("\n=== LOOKING FOR PROJECT REFERENCES ===");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages.Where(m => m.Text != null && m.Text.Contains("ProjectReference")))
{
    Console.WriteLine($"  {m.Text}");
}

// Get source content around errors
Console.WriteLine("\n=== SOURCE FILES IN BINLOG ===");
var sourceFiles = build.FindChildrenRecursive<SourceFile>();
foreach (var sf in sourceFiles)
{
    Console.WriteLine($"  {sf.Name}");
}
EOF
