cd /tmp/binlog-reader && cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

Console.WriteLine("=== BUILD SUCCEEDED: " + build.Succeeded + " ===");
Console.WriteLine("\n=== PROJECTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} (SourceFilePath={p.SourceFilePath})");
}

Console.WriteLine("\n=== ALL ERRORS WITH CONTEXT ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    var parent = e.Parent;
    Console.WriteLine($"\nError: {e.Code}: {e.Text}");
    Console.WriteLine($"  File: {e.File}({e.LineNumber},{e.ColumnNumber})");
    Console.WriteLine($"  Project: {e.ProjectFile}");
    Console.WriteLine($"  Parent: {parent?.GetType().Name} - {parent}");
}

Console.WriteLine("\n=== FAILED TARGETS ===");
var targets = build.FindChildrenRecursive<Target>();
foreach (var t in targets.Where(t => !t.Succeeded))
{
    Console.WriteLine($"  Failed target: {t.Name} in {t.Project?.SourceFilePath}");
}
EOF
